// Ticket 049 FR-2: what each voice agent says and is told, per language. The English prompt is the agent's base
// configuration in the ElevenLabs dashboard (docs/elevenlabs-*-agent.md, unchanged wording); Hindi and Telugu are the
// agent's language presets (first message + prompt), generated by `npx tsx scripts/elevenlabs-language-presets.ts`.
// Instructions to the model stay in English (reviewable by the team); everything the agent SAYS word for word (first
// message, safety message, button labels, answer words) comes from messages/{en,hi,te}.json, identical to the page.
import type { Locale } from "@/lib/i18n/config";

export type AgentPrompt = {
  language: Locale;
  /** ElevenLabs syntax (`{{age_band}}`): the agent's first message in this language. */
  firstMessage: string;
  systemPrompt: string;
  /** The 108/112 message the agent says word for word on a red flag (identical to the page text). */
  safetyMessage: string;
};

/** Language-specific guidance written for each language file (`prompts/<lang>.ts`). */
export type PromptLanguage = {
  code: Locale;
  /** "Telugu (తెలుగు)": how the prompt names the language. */
  name: string;
  /** Extra guidance for this language (register, loanwords, numbers). Empty for English. */
  notes: string;
};

/** Comma-separated lexicon synonyms as a prompt list: `"a", "b"`. */
export function quoteWords(value: string): string {
  return value
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean)
    .map((s) => `"${s}"`)
    .join(", ");
}

/** The language line every non-English prompt starts its rules with. */
export function speakOnly(lang: PromptLanguage): string {
  return `You speak ${lang.name} only (call language code {{language}}). ${lang.notes}`.trim();
}
